      href: Router.RelativePathString | Router.ExternalPathString | `/addresses${`?${string}` | `#${string}` | ''}` | `/admin-delivery-partners${`?${string}` | `#${string}` | ''}` | `/admin-earnings${`?${string}` | `#${string}` | ''}` | `/admin${`?${string}` | `#${string}` | ''}` | `/auth${`?${string}` | `#${string}` | ''}` | `/become-seller${`?${string}` | `#${string}` | ''}` | `/chand${`?${string}` | `#${string}` | ''}` | `/checkout${`?${string}` | `#${string}` | ''}` | `/delivery-address${`?${string}` | `#${string}` | ''}` | `/delivery-partner${`?${string}` | `#${string}` | ''}` | `/${`?${string}` | `#${string}` | ''}` | `/language${`?${string}` | `#${string}` | ''}` | `/notifications${`?${string}` | `#${string}` | ''}` | `/order-tracking${`?${string}` | `#${string}` | ''}` | `/orders${`?${string}` | `#${string}` | ''}` | `/password-reset${`?${string}` | `#${string}` | ''}` | `/payment-methods${`?${string}` | `#${string}` | ''}` | `/referral-dashboard${`?${string}` | `#${string}` | ''}` | `/referral${`?${string}` | `#${string}` | ''}` | `/request${`?${string}` | `#${string}` | ''}` | `/retail-prices${`?${string}` | `#${string}` | ''}` | `/seller-earnings${`?${string}` | `#${string}` | ''}` | `/services${`?${string}` | `#${string}` | ''}` | `/shops${`?${string}` | `#${string}` | ''}` | `/_sitemap${`?${string}` | `#${string}` | ''}` | `${'/(tabs)'}/account${`?${string}` | `#${string}` | ''}` | `/account${`?${string}` | `#${string}` | ''}` | `${'/(tabs)'}/cart${`?${string}` | `#${string}` | ''}` | `/cart${`?${string}` | `#${string}` | ''}` | `${'/(tabs)'}/categories${`?${string}` | `#${string}` | ''}` | `/categories${`?${string}` | `#${string}` | ''}` | `${'/(tabs)'}${`?${string}` | `#${string}` | ''}` | `/${`?${string}` | `#${string}` | ''}` | `${'/(tabs)'}/search${`?${string}` | `#${string}` | ''}` | `/search${`?${string}` | `#${string}` | ''}` | `/restaurant/account${`?${string}` | `#${string}` | ''}` | `/restaurant/addresses${`?${string}` | `#${string}` | ''}` | `/restaurant/cart${`?${string}` | `#${string}` | ''}` | `/restaurant/categories${`?${string}` | `#${string}` | ''}` | `/restaurant/checkout${`?${string}` | `#${string}` | ''}` | `/restaurant/dashboard${`?${string}` | `#${string}` | ''}` | `/restaurant${`?${string}` | `#${string}` | ''}` | `/restaurant/menu${`?${string}` | `#${string}` | ''}` | `/restaurant/order-confirmation${`?${string}` | `#${string}` | ''}` | `/restaurant/search${`?${string}` | `#${string}` | ''}` | `/restaurant/support${`?${string}` | `#${string}` | ''}` | `/restaurant/orders${`?${string}` | `#${string}` | ''}` | `/seller/orders${`?${string}` | `#${string}` | ''}` | `/seller/products${`?${string}` | `#${string}` | ''}` | `/seller/support${`?${string}` | `#${string}` | ''}` | { pathname: Router.RelativePathString | Router.ExternalPathString | `/addresses` | `/admin-delivery-partners` | `/admin-earnings` | `/admin` | `/auth` | `/become-seller` | `/chand` | `/checkout` | `/delivery-address` | `/delivery-partner` | `/` | `/language` | `/notifications` | `/order-tracking` | `/orders` | `/password-reset` | `/payment-methods` | `/referral-dashboard` | `/referral` | `/request` | `/retail-prices` | `/seller-earnings` | `/services` | `/shops` | `/_sitemap` | `${'/(tabs)'}/account` | `/account` | `${'/(tabs)'}/cart` | `/cart` | `${'/(tabs)'}/categories` | `/categories` | `${'/(tabs)'}` | `/` | `${'/(tabs)'}/search` | `/search` | `/restaurant/account` | `/restaurant/addresses` | `/restaurant/cart` | `/restaurant/categories` | `/restaurant/checkout` | `/restaurant/dashboard` | `/restaurant` | `/restaurant/menu` | `/restaurant/order-confirmation` | `/restaurant/search` | `/restaurant/support` | `/restaurant/orders` | `/seller/orders` | `/seller/products` | `/seller/support`; params?: Router.UnknownInputParams; } | `/+not-found${`?${string}` | `#${string}` | ''}` | `/category/${Router.SingleRoutePart<T>}` | `/product/${Router.SingleRoutePart<T>}` | `/restaurant/${Router.SingleRoutePart<T>}` | `/restaurant/ord