import Feather from "@react-native-vector-icons/feather";
import { Image } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import { useFocusEffect, useRouter } from "expo-router";
import { useCallback, useEffect, useState } from "react";
import {
  FlatList,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  StatusBar,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { BrandLogo } from "@/src/components/BrandLogo";
import { AnnouncementBanner } from "@/src/components/AnnouncementBanner";
import { useAuth } from "@/src/store/auth";
import { api } from "@/src/lib/api";
import { Alert } from "@/src/utils/alert";
import { ProductCard } from "@/src/components/ProductCard";
import {
  CATEGORIES,
  POPULAR_PRODUCTS,
  QUICK_DELIVERY_PRODUCTS,
  SERVICES,
} from "@/src/data/catalog";
import { useCatalogProducts } from "@/src/data/useCatalogProducts";
import { useT } from "@/src/i18n";
import { useLocationCtx } from "@/src/store/location";
import { makeStyles, radius, spacing, useTheme } from "@/src/theme";

const DEFAULT_LOCATION = "Set delivery location";

export default function HomeScreen() {
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const styles = useStyles();
  const { colors } = useTheme();
  const { location, setLocation } = useLocationCtx();
  const { t } = useT();
  const { liveProducts } = useCatalogProducts();
  const { user } = useAuth();
  const [referralClaim, setReferralClaim] = useState<{ userId: string; show: boolean } | null>(null);
  const showProminentReferral = user?.role === "customer" && referralClaim?.userId === user.id && referralClaim.show;
  const [unread, setUnread] = useState(0);

  // Task 20: unread in-app notification badge, refreshed whenever Home regains focus.
  useFocusEffect(useCallback(() => {
    let active = true;
    if (!user?.id) { setUnread(0); return () => { active = false; }; }
    api.get<{ unread: number }>("/notifications/unread-count").then((r) => { if (active) setUnread(Number(r.unread) || 0); }).catch(() => {});
    return () => { active = false; };
  }, [user?.id]));
  useEffect(() => {
    let active = true;
    if (!user?.id || user.role !== "customer") return () => { active = false; };
    void api.post<{ show_prominent: boolean }>("/referrals/home-banner-claim", {}).then((result) => {
      if (active) setReferralClaim({ userId: user.id, show: Boolean(result.show_prominent) });
    }).catch(() => { if (active) setReferralClaim({ userId: user.id, show: false }); });
    return () => { active = false; };
  }, [user?.id, user?.role]);
  const quickProducts = liveProducts.length ? liveProducts.slice(0, 6) : QUICK_DELIVERY_PRODUCTS.slice(0, 6);
  const livePopular = liveProducts.filter((p) => p.popular);
  const popularProducts = liveProducts.length ? (livePopular.length ? livePopular.slice(0, 6) : liveProducts.slice(0, 6)) : POPULAR_PRODUCTS.slice(0, 6);
  const [locModalOpen, setLocModalOpen] = useState(false);
  const [locInput, setLocInput] = useState(
    location === DEFAULT_LOCATION ? "" : location,
  );

  // Re-sync the modal input with the currently-saved location every time
  // the modal is opened so stale text from a prior session isn't shown
  // after the address was changed from Account settings.
  const [locationSync, setLocationSync] = useState({ open: locModalOpen, location });
  if (locationSync.open !== locModalOpen || locationSync.location !== location) {
    setLocationSync({ open: locModalOpen, location });
    if (locModalOpen) setLocInput(location === DEFAULT_LOCATION ? "" : location);
  }

  return (
    <View style={styles.root}>
      <StatusBar barStyle="dark-content" />
      {/* Sticky Header */}
      <View
        style={[styles.header, { paddingTop: insets.top + spacing.sm }]}
      >
        <View style={styles.topRow}>
          <View style={styles.brandLogoWrap}>
            <BrandLogo testID="brand-logo" size="md" />
          </View>
          <View style={styles.headerActions}>
            <Pressable testID="header-voice-search" accessibilityRole="button" accessibilityLabel="Open CHAND AI voice typing" onPress={() => router.push("/chand?voice=1")} style={styles.headerAction}>
              <Feather name="mic" size={19} color={colors.brandForest} />
            </Pressable>
            <Pressable testID="header-language" accessibilityRole="button" accessibilityLabel="Choose language" onPress={() => router.push("/language")} style={styles.headerAction}>
              <Feather name="globe" size={19} color={colors.brandForest} />
            </Pressable>
            <Pressable testID="header-notifications" accessibilityRole="button" accessibilityLabel={unread ? `${unread} unread notifications` : "View notifications"} onPress={() => router.push(user ? "/notifications" : "/orders")} style={styles.headerAction}>
              <Feather name="bell" size={19} color={colors.brandForest} />
              {unread > 0 && <View style={styles.bellBadge} testID="header-notifications-badge"><Text style={styles.bellBadgeText}>{unread > 9 ? "9+" : unread}</Text></View>}
            </Pressable>
            <Pressable testID="header-account" accessibilityRole="button" accessibilityLabel="Open account" onPress={() => router.push("/(tabs)/account")} style={[styles.headerAction, styles.headerAccountAction]}>
              <Feather name="user" size={19} color="#FFFFFF" />
            </Pressable>
          </View>
        </View>
      </View>
      {/* Search sits on the mint page surface, directly below the yellow brand header. */}
      <View style={styles.searchArea}>
        <View style={styles.searchRow}>
          <Pressable
            testID="home-search-bar"
            accessibilityRole="button"
            onPress={() => router.push("/(tabs)/search")}
            style={styles.searchBar}
          >
            <Feather name="search" size={18} color={colors.brandForest} />
            <Text style={styles.searchPlaceholder}>{t("home.searchPlaceholder")}</Text>
          </Pressable>
          <Pressable
            testID="home-filter-button"
            accessibilityRole="button"
            accessibilityLabel="Browse categories and filters"
            onPress={() => router.push("/(tabs)/categories")}
            style={styles.filterButton}
          >
            <Feather name="sliders" size={19} color={colors.brandForest} />
          </Pressable>
        </View>

      </View>

      <ScrollView
        showsVerticalScrollIndicator={false}
        contentContainerStyle={{ paddingBottom: spacing.xxl }}
      >
        {/* Hero Banner */}
        <View style={styles.heroWrap}>
          <Pressable testID="fresh-groceries-banner" accessibilityRole="button" onPress={() => router.push("/(tabs)/categories")} style={styles.hero}>
            <Image
              source="https://images.unsplash.com/photo-1542838132-92c53300491e?crop=entropy&cs=srgb&fm=jpg&w=1200&q=80"
              style={styles.heroImage}
              contentFit="cover"
            />
            <LinearGradient
              colors={["#D9F5DF", "#D9F5DFD9", "#D9F5DF12"]}
              start={{ x: 0, y: 0.5 }}
              end={{ x: 1, y: 0.5 }}
              style={StyleSheet.absoluteFill}
            />
            <View style={styles.heroContent}>
              <Text style={styles.heroTitle}>Fresh Groceries</Text>
              <Text style={styles.heroTitle}><Text style={styles.heroRed}>& Delicious Food</Text></Text>
              <Text style={styles.heroSub}>Fruits • Vegetables • Daily Essentials</Text>
              <Text style={styles.heroSub}> & Restaurant Favorites</Text>
              <View style={styles.heroCta}>
                <Text style={styles.heroCtaText}>Shop Now</Text>
                <Feather name="arrow-right" size={14} color="#FFFFFF" />
              </View>
            </View>
          </Pressable>
          <View style={styles.carouselDots} accessibilityLabel="Promotional banners">
            {[0,1,2,3,4].map((dot) => <View key={dot} style={[styles.carouselDot, dot === 0 && styles.carouselDotActive]} />)}
          </View>
        </View>

        {user?.role === "customer" && (
          <View style={[styles.referralBanner, showProminentReferral && styles.referralBannerProminent]} testID={showProminentReferral ? "referral-first-login-banner" : "referral-returning-banner"}>
            <View style={styles.referralBannerIcon}><Feather name="gift" size={showProminentReferral ? 24 : 19} color="#FFFFFF" /></View>
            <View style={styles.referralBannerCopy}>
              <Text style={styles.referralBannerTitle}>{showProminentReferral ? "Referral & Earn — Welcome!" : "Refer friends & earn ₹500"}</Text>
              <Text style={styles.referralBannerText}>{showProminentReferral ? "Refer 10 eligible new customers to earn a total reward of ₹500. Each must complete at least ₹100 eligible shopping, delivery, payment confirmation and admin review." : "10 eligible new customers = ₹500 total reward, after shopping, delivery, payment and review checks."}</Text>
            </View>
            <Pressable accessibilityRole="button" testID="home-referral-open" onPress={() => router.push("/referral-dashboard")} style={styles.referralBannerButton}>
              <Text style={styles.referralBannerButtonText}>Open</Text>
            </Pressable>
          </View>
        )}

        {/* Four separate discovery entry points; Shopping and Restaurant remain separate routes. */}
        <AnnouncementBanner />
        <View style={styles.modeGrid}>
          <ModeCard testID="online-shops-card" title="Online Shops" subtitle="Shop from your favorite online stores" artwork="online" onPress={() => router.push("/shops?type=online")} />
          <ModeCard testID="offline-shops-card" title="Offline Shops" subtitle="Support local businesses in your town" artwork="offline" onPress={() => router.push("/shops?type=offline")} />
          <ModeCard testID="restaurant-mode-card" title="Restaurants" subtitle="Tasty food, great flavors, delivered" artwork="restaurant" onPress={() => router.push("/restaurant")} />
          <ModeCard testID="home-services-card" title="Home Services" subtitle="Trusted help for your home" artwork="services" onPress={() => router.push("/services")} />
        </View>



        {/* Grocery Categories */}
        <SectionHeader title={t("home.shopByCategory")} onSeeAll={() => router.push("/(tabs)/categories")} />
        <View style={styles.categoryGrid} testID="home-category-grid">
          {CATEGORIES.map((item) => (
            <Pressable
              key={item.id}
              testID={`home-cat-${item.id}`}
              accessibilityRole="button"
              onPress={() => router.push(`/category/${item.id}`)}
              style={[styles.catTile, { backgroundColor: "#DFF8E7", borderColor: "#C9F0D7" }]}
            >
              <Image source={item.image} style={styles.catImage} contentFit="cover" />
              <Text style={styles.catName} numberOfLines={2}>
                {{
                  "fruits-veggies": "Fruits & Vegetables",
                  "dairy-breakfast": "Dairy & Breakfast",
                  snacks: "Snacks & Munchies",
                  beverages: "Beverages",
                  bakery: "Bakery",
                  "personal-care": "Personal Care",
                  household: "Household Essentials",
                }[item.id] ?? item.name}
              </Text>
            </Pressable>
          ))}
        </View>

        {/* Keep the existing delivery-location selector functional without expanding the yellow header. */}
        <Pressable
          testID="location-selector"
          accessibilityRole="button"
          onPress={() => setLocModalOpen(true)}
          style={styles.locRow}
        >
          <Feather name="map-pin" size={14} color={colors.brandPrimary} />
          <Text style={styles.locLabel}>{t("home.deliverTo")}</Text>
          <Text style={styles.locValue} numberOfLines={1}>
            {location === DEFAULT_LOCATION ? t("home.setLocation") : location}
          </Text>
          <Feather name="chevron-down" size={16} color={colors.onSurfaceSecondary} />
        </Pressable>

        {/* Shared CHAND assistant entry; keeps existing Shopping/Restaurant modes intact. */}
        <View style={styles.chandWrap}>
          <Pressable testID="chand-home-entry" accessibilityRole="button" accessibilityLabel="Open CHAND by COME-IN assistant" onPress={() => router.push("/chand")} style={styles.chandCard}>
            <View style={styles.chandIcon}><Feather name="moon" size={23} color="#FFFFFF" /></View>
            <View style={{ flex: 1 }}>
              <Text style={styles.chandTitle}>Meet CHAND</Text>
              <Text style={styles.chandSub}>by COME-IN · आपका अपना स्मार्ट साथी</Text>
              <Text style={styles.chandHint}>Your Smart Shopping Assistant · Live catalog search; AI provider optional</Text>
            </View>
            <Feather name="arrow-up-right" size={20} color="#FFFFFF" />
          </Pressable>
        </View>

        {/* Quick Delivery */}
        <View style={styles.quickHeader}>
          <View style={styles.quickBadge}>
            <Feather name="zap" size={12} color={colors.onBrandSecondary} />
            <Text style={styles.quickBadgeText}>{t("home.minBadge")}</Text>
          </View>
          <Text style={styles.quickTitle}>{t("home.quickDelivery")}</Text>
        </View>
        <FlatList
          data={quickProducts}
          keyExtractor={(p) => p.id}
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={{ paddingHorizontal: spacing.lg, gap: spacing.md }}
          renderItem={({ item }) => <ProductCard product={item} width={160} />}
        />

        {/* Popular Products */}
        <SectionHeader title={t("home.popular")} onSeeAll={() => router.push("/(tabs)/categories")} />
        <View style={styles.popularGrid}>
          {popularProducts.map((p) => (
            <View key={p.id} style={styles.gridItem}>
              <ProductCard product={p} />
            </View>
          ))}
        </View>

        {/* Home Services */}
        <SectionHeader title={t("home.homeServices")} onSeeAll={() => router.push("/services")} />
        <FlatList
          data={SERVICES.slice(0, 4)}
          keyExtractor={(s) => s.id}
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={{ paddingHorizontal: spacing.lg, gap: spacing.md }}
          renderItem={({ item }) => (
            <Pressable
              testID={`home-service-${item.id}`}
              onPress={() => router.push("/services")}
              style={styles.serviceCard}
            >
              <Image source={item.image} style={styles.serviceImg} contentFit="cover" />
              <View style={styles.serviceInfo}>
                <Text style={styles.serviceTitle} numberOfLines={1}>
                  {item.title}
                </Text>
                <Text style={styles.serviceTag} numberOfLines={1}>
                  {item.tagline}
                </Text>
                <Text style={styles.servicePrice}>{item.price}</Text>
              </View>
            </Pressable>
          )}
        />

      </ScrollView>

      {/* Location modal */}
      <Modal
        visible={locModalOpen}
        animationType="slide"
        transparent
        onRequestClose={() => setLocModalOpen(false)}
      >
        <Pressable style={styles.modalBackdrop} onPress={() => setLocModalOpen(false)} />
        <View style={[styles.modalSheet, { paddingBottom: insets.bottom + spacing.lg }]}>
          <View style={styles.modalHandle} />
          <Text style={styles.modalTitle}>{t("home.whereDeliver")}</Text>
