// Come In — Auth screen (sign in / register).
//
// This replaces the old "Sign in coming soon" modal. On success we navigate
// back; if the user came here with ?next=/some/path we honor that.
import Feather from "@react-native-vector-icons/feather";
import { useLocalSearchParams, useRouter } from "expo-router";
import { useEffect, useState } from "react";
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { BrandLogo } from "@/src/components/BrandLogo";
import { useAuth } from "@/src/store/auth";
import { storage } from "@/src/utils/storage";
import { makeStyles, radius, spacing, useTheme } from "@/src/theme";

type Mode = "signin" | "signup";

export default function AuthScreen() {
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const styles = useStyles();
  const { colors } = useTheme();
  const { login, register } = useAuth();
  const { next, ref, mode: initialMode } = useLocalSearchParams<{ next?: string; ref?: string; mode?: string }>();
  const [mode, setMode] = useState<Mode>(initialMode === "signup" ? "signup" : "signin");
  const [referralCode, setReferralCode] = useState(typeof ref === "string" ? ref.toUpperCase() : "");
  const [previousRoute, setPreviousRoute] = useState({ ref, mode: initialMode });
  if (previousRoute.ref !== ref || previousRoute.mode !== initialMode) {
    setPreviousRoute({ ref, mode: initialMode });
    if (typeof ref === "string" && ref) setReferralCode(ref.toUpperCase());
    if (initialMode === "signup") setMode("signup");
  }
  useEffect(() => {
    const incoming = typeof ref === "string" ? ref : "";
    if (incoming) { void storage.setItem("comein.pendingReferralCode", incoming.toUpperCase()); }
    else void storage.getItem<string>("comein.pendingReferralCode", "").then((value) => { if (value) setReferralCode(value.toUpperCase()); });
  }, [ref, initialMode]);

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const submit = async () => {
    setError(null);
    setLoading(true);
    try {
      if (mode === "signin") {
        await login(email.trim(), password);
        // An existing account cannot retroactively claim a referral; discard this device's pending code.
        await storage.removeItem("comein.pendingReferralCode");
      } else {
        if (!name.trim()) {
          setError("Please enter your name");
          setLoading(false);
          return;
        }
        const savedReferral = referralCode || (await storage.getItem<string>("comein.pendingReferralCode", "")) || "";
        await register(name.trim(), email.trim(), password, phone.trim() || undefined, savedReferral || undefined);
        if (savedReferral) await storage.removeItem("comein.pendingReferralCode");
      }
      if (next && typeof next === "string") router.replace(next as any);
      else router.replace("/(tabs)/account");
    } catch (e: any) {
      setError(e?.message || "Could not continue");
    } finally {
      setLoading(false);
    }
  };

  return (
    <KeyboardAvoidingView
      style={styles.root}
      behavior={Platform.OS === "ios" ? "padding" : undefined}
    >
      <ScrollView
        contentContainerStyle={{ padding: spacing.lg, paddingTop: insets.top + spacing.lg }}
        keyboardShouldPersistTaps="handled"
      >
        <Pressable
          testID="auth-back-btn"
          onPress={() => router.back()}
          style={styles.iconBtn}
        >
          <Feather name="arrow-left" size={20} color={colors.onSurface} />
        </Pressable>

        <View style={{ alignItems: "center", marginVertical: spacing.lg }}>
          <BrandLogo size="md" />
        </View>

        <Text style={styles.title}>
          {mode === "signin" ? "Welcome back" : "Create your Come In account"}
        </Text>
        <Text style={styles.sub}>
          {mode === "signin"
            ? "Sign in to track orders, save addresses and open your shop."
            : "Sign up once to shop, use local services and manage your shop."}
        </Text>

        {mode === "signup" && (
          <>
            <Label text="Full name" />
            <Input
              testID="auth-name"
              icon="user"
              value={name}
              onChangeText={setName}
              placeholder="Rohit Kumar"
            />
          </>
        )}

        <Label text="Email" />
        <Input
          testID="auth-email"
          icon="mail"
          value={email}
          onChangeText={setEmail}
          placeholder="you@example.com"
          autoCapitalize="none"
          keyboardType="email-address"
        />

        {mode === "signup" && (
          <>
            <Label text="Phone (optional)" />
            <Input
              testID="auth-phone"
              icon="phone"
              value={phone}
              onChangeText={setPhone}
              placeholder="+91 98123 00000"
              keyboardType="phone-pad"
            />
          </>
        )}

        <Label text="Password" />
        <Input
          testID="auth-password"
          icon="lock"
          value={password}
          onChangeText={setPassword}
          placeholder="At least 6 characters"
          secureTextEntry
        />

        {error && (
          <View style={styles.errorBox} testID="auth-error">
            <Feather name="alert-circle" size={14} color={colors.error} />
            <Text style={styles.errorText}>{error}</Text>
          </View>
        )}

        <Pressable
          testID="auth-submit"
          disabled={loading}
          onPress={submit}
          style={[styles.submit, loading && { opacity: 0.6 }]}
        >
          {loading ? (
            <ActivityIndicator color={colors.onBrandPrimary} />
          ) : (
            <Text style={styles.submitText}>
              {mode === "signin" ? "Sign in" : "Create account"}
            </Text>
          )}
        </Pressable>

        {mode === "signin" && (
          <Pressable onPress={() => router.push("/password-reset" as never)} style={styles.switchRow}>
            <Text style={[styles.switchText, { color: colors.brandPrimary, fontWeight: "800" }]}>Forgot password?</Text>
          </Pressable>
        )}

        <Pressable
          testID="auth-switch-mode"
          onPress={() => setMode(mode === "signin" ? "signup" : "signin")}
          style={styles.switchRow}
        >
          <Text style={styles.switchText}>
            {mode === "signin" ? "New to Come In? " : "Already have an account? "}
            <Text style={[styles.switchText, { color: colors.brandPrimary, fontWeight: "800" }]}>
              {mode === "signin" ? "Create account" : "Sign in"}
            </Text>
          </Text>
        </Pressable>

        <View style={styles.note}>
          <Feather name="info" size={12} color={colors.muted} />
          <Text style={styles.noteText}>
            Phone OTP, Google and Razorpay sign-in will activate once their keys are configured. For
            now, email + password works everywhere.
          </Text>
        </View>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

function Label({ text }: { text: string }) {
  const styles = useStyles();
  return <Text style={styles.label}>{text}</Text>;
}

function Input({
  testID,
  icon,
  ...rest
}: {
  testID: string;
  icon: React.ComponentProps<typeof Feather>["name"];
} & React.ComponentProps<typeof TextInput>) {
  const styles = useStyles();
  const { colors } = useTheme();
  return (
    <View style={styles.inputWrap}>
      <Feather name={icon} size={16} color={colors.brandPrimary} />
      <TextInput
        testID={testID}
        placeholderTextColor={colors.muted}
        style={styles.input}
        {...rest}
      />
    </View>
  );
}

