function demoReply(message: string, role: RoleMode): string {
  const q = message.toLowerCase();
  // Deterministic, offline guidance only. Never claim that an order, payment,
  // complaint, cancellation, or refund has been changed by this chat.
  if (/(payment.*(deduct|debit).*(order|missing)|deduct.*but.*order|order.*not.*placed|ऑर्डर.*नहीं.*मिला)/i.test(q)) {
    return "Demo Mode: Agar payment deduct hui hai lekin order COME-IN mein nahi dikh raha, pehle Orders aur payment app/bank ka status check karein. Dobara payment turant na karein. Help & Support mein payment issue select karke date, amount aur transaction reference (sensitive credentials nahi) likhein. CHAND yahan payment ya order verify nahi kar raha.";
  }
  if (/(duplicate.*(payment|charge)|double.*(payment|charge)|twice.*paid|दो बार.*(पेमेंट|पैसे))/i.test(q)) {
    return "Demo Mode: Duplicate payment ke liye dono transaction references aur amounts note karein, aur Help & Support mein Payment issue submit karein. OTP, PIN, CVV ya password share na karein. Yeh chat duplicate charge verify ya reverse nahi karti.";
  }
  if (/(missing item|item missing|item.*not.*received|कम.*आया|सामान.*नहीं.*मिला|छूटा हुआ)/i.test(q)) {
    return "Demo Mode: Missing item ke liye order select karke item ka naam, quantity aur package/photo ka detail Help & Support mein dein. CHAND order inspect nahi kar raha aur complaint tabhi record hogi jab existing support API se confirmation mile.";
  }
  if (/(delay|delayed|late delivery|not arrived|नहीं पहुँचा|देरी)/i.test(q)) {
    return "Demo Mode: Delayed order ke liye existing Orders/Order Tracking screen par latest backend status check karein. Agar status stale ho ya order na aaye, Help & Support mein order reference aur delay details bhejein. Main live location ya delivery time confirm nahi kar sakta.";
  }
  if (/(wrong item|incorrect item|damaged|broken|खराब|गलत सामान|टूटा)/i.test(q)) {
    return "Demo Mode: Wrong ya damaged item ke liye order select karein aur item, quantity, issue aur available photo details Help & Support mein dein. Return/replacement ya refund approve nahi hua hai; actual next step support team ke backend status par depend karega.";
  }
  if (/(cancel|cancellation|रद्द)/i.test(q)) {
    return "Demo Mode: Cancellation ke liye existing Orders screen par us order ke available actions aur current status check karein. Main yahan order cancel nahi kar sakta. Agar cancel option nahi hai ya status unclear hai, Help & Support mein order reference ke saath request bhejein.";
  }
  if (/(refund.*status|status.*refund|refund kab|रिफंड.*(स्टेटस|कब)|पैसे.*वापस)/i.test(q)) {
    return "Demo Mode: Actual refund status sirf authenticated order/support details mein backend se report hua status hai. Help & Support mein apna order select karke jo status dikhaya gaya hai woh check karein. Customer refund-request API available nahi hai; support case refund approval ya completed payment nahi hota.";
  }
  if (/(refund|रिफंड)/i.test(q)) {
    return "Demo Mode: Refund help ke liye Help & Support mein apna order select karke details submit kar sakte hain. Existing API sirf support case banati hai; CHAND refund request, approval ya payment execute nahi karta. Backend status confirmation ke bina refund complete nahi maana ja sakta.";
  }
  if (/(order|ऑर्डर|status|स्टेटस|track)/i.test(q)) {
    return "Demo Mode: Main yahan aapka real order record access nahi kar raha. Apne actual orders aur backend-reported status ke liye COME-IN ke Orders/Order Tracking page par jaayein.";
  }
  if (/(electrician|plumb|clean|service|provider|सेवा|इलेक्ट्रीशियन)/i.test(q) || role === "services") {
    return "Demo Mode: Home Services integration abhi live provider availability se connected nahi hai. Aap existing Home Services page khol kar available categories dekh sakte hain; yahan koi provider ya booking confirm nahi ki ja rahi.";
  }
  if (/(restaurant|dinner|food|menu|खाना|डिनर)/i.test(q) || role === "restaurant") {
    return "Demo Mode: Restaurant Mode ka live menu yahan query nahi hua. Actual restaurants aur menu dekhne ke liye Restaurant Mode kholein. Main sample recommendation ya order availability ko real nahi bataunga.";
  }
  if (/(stock|product|seller|shop|sales|स्टॉक|दुकान)/i.test(q) || role === "shopkeeper") {
    return "Demo Mode: Seller records aur stock live backend se load nahi kiye gaye. Apne authorized listings aur orders ke liye existing seller screens use karein. Main yahan sirf reply draft aur planning mein madad kar sakta hoon.";
  }
  if (/(ration|grocery|₹|budget|cheap|cheapest|सस्ता|किराना)/i.test(q)) {
    return "Demo Mode: Budget samajh gaya. Live catalog, stock aur prices abhi CHAND se connected nahi hain, isliye main products ya prices invent nahi karunga. COME-IN Categories/Search mein current options check karein.";
  }
  return "Namaste! Main CHAND by COME-IN hoon — aapka apna smart saathi. Yeh no-cost Demo Mode hai; abhi live AI ya private account data connected nahi hai. Main general guidance aur reply drafts mein madad kar sakta hoon. Agar request live order, payment, booking ya account data maangti hai, to main use yahan verify nahi kar sakta; relevant existing COME-IN screen ya Help & Support use karein. Main unavailable information invent nahi karunga.";
}


type AssistantProduct = {
  id: string; name: string; brand?: string; category?: string; category_id?: string; price_inr?: number; mrp_inr?: number | null; price?: number; mrp?: number | null;
  stock?: number; unit?: string; shop_id?: string; shop_name?: string; shop_type?: string; description?: string; image_url?: string | null;
  available?: boolean; shop_delivery_available?: boolean; shop_pickup_available?: boolean;
  sell_by?: "pack" | "weight" | "volume"; measure?: Product["measure"];
  variants?: Array<{ id: string; name?: string; unit?: string; price_inr?: number; mrp_inr?: number; price?: number; mrp?: number; stock?: number; available?: boolean }>;
};
type AssistantContext = {
  source: string; answer?: string | null; ai_provider?: string; categories: string[];
  products: AssistantProduct[];
  shops: Array<{ name: string; shop_type?: string; area?: string; category?: string }>;
  restaurants: Array<{ name: string; cuisine?: string; available?: boolean }>;
  restaurant_menu_items: Array<{ name: string; restaurant_name?: string; category?: string; price_inr?: number; description?: string }>;
  home_services: Array<{ name: string; category?: string; service_area?: string; visit_fee_inr?: number | null }>;
  counts: { products: number; shops: number; restaurants: number; home_services: number };
};

function mapAssistantProducts(items: AssistantProduct[] = []): Product[] {
  return items.filter((item) => item.id && item.name && item.available !== false).map((item): Product => {
    const categoryId = item.category_id || "grocery";
    return {
      id: item.id, name: item.name, brand: item.brand || "", unit: item.unit || "unit",
      price: Number(item.variants?.[0]?.price_inr ?? item.variants?.[0]?.price ?? item.price_inr ?? item.price ?? 0),
      mrp: (item.variants?.[0]?.mrp_inr ?? item.variants?.[0]?.mrp) == null ? ((item.mrp_inr ?? item.mrp) == null ? undefined : Number(item.mrp_inr ?? item.mrp)) : Number(item.variants?.[0]?.mrp_inr ?? item.variants?.[0]?.mrp),
      image: resolveImage(item.image_url) || "", categoryId, description: item.description || "",
      stock: item.stock, source: "live", shopId: item.shop_id, shopName: item.shop_name, shopType: item.shop_type,
      shopDeliveryAvailable: item.shop_delivery_available, shopPickupAvailable: item.shop_pickup_available,
      sellBy: item.sell_by || "pack", measure: item.measure,
      variants: (item.variants || []).filter((variant) => variant.id).map((variant) => ({
        id: variant.id, unit: variant.unit || item.unit || "unit", price: Number(variant.price_inr ?? variant.price ?? item.price_inr ?? item.price ?? 0),
        mrp: (variant.mrp_inr ?? variant.mrp) == null ? undefined : Number(variant.mrp_inr ?? variant.mrp), stock: variant.stock, available: variant.available,
      })),
    };
  });
}

function groundedReply(data: AssistantContext, lang: string, t: (key: string) => string): string {
  const lines: string[] = [];
  if (data.products.length) {
    lines.push(`${t("chand.results.products")}:`);
    for (const p of data.products.slice(0, 6)) {
      lines.push(`• ${p.name} — ${p.price_inr == null ? "Price unavailable" : `₹${p.price_inr}`} · ${t("chand.shop")}: ${p.shop_name || "—"}${p.stock != null ? ` · ${t("chand.stock")}: ${p.stock}` : ""}${p.description ? `\n  ${p.description}` : ""}`);
    }
  }
  if (data.shops.length) lines.push(`${t("chand.results.shops")}:\n${data.shops.slice(0, 5).map(x => `• ${x.name}${x.category ? ` · ${x.category}` : ""}${x.area ? ` · ${t("chand.area")}: ${x.area}` : ""}`).join("\n")}`);
  if (data.restaurants.length) lines.push(`${t("chand.results.restaurants")}:\n${data.restaurants.slice(0, 5).map(x => `• ${x.name}${x.cuisine ? ` · ${x.cuisine}` : ""}${x.available ? " · Available" : ""}`).join("\n")}`);
  if (data.restaurant_menu_items?.length) lines.push(`${t("chand.results.menu")}:\n${data.restaurant_menu_items.slice(0, 6).map(x => `• ${x.name} — ${x.price_inr == null ? "Price unavailable" : `₹${x.price_inr}`} · ${x.restaurant_name || ""}${x.description ? `\n  ${x.description}` : ""}`).join("\n")}`);
  if (data.home_services.length) lines.push(`${t("chand.results.services")}:\n${data.home_services.slice(0, 5).map(x => `• ${x.name} — ${x.category || ""}${x.service_area ? ` · ${x.service_area}` : ""}${x.visit_fee_inr != null ? ` · ${t("chand.servicefee")}: ₹${x.visit_fee_inr}` : ""}`).join("\n")}`);
  if (data.categories.length) lines.push(`${t("chand.results.categories")}: ${data.categories.slice(0, 12).join(", ")}`);
  if (!lines.length) return t("chand.noresults");
  const prefix = lang === "hi" ? "COME-IN के मौजूदा सार्वजनिक डेटा से मिली जानकारी:" : lang === "pa" ? "COME-IN ਦੇ ਮੌਜੂਦਾ ਜਨਤਕ ਡਾਟੇ ਤੋਂ ਜਾਣਕਾਰੀ:" : "Results from current public COME-IN listings:";
  return `${prefix}\n\n${lines.join("\n\n")}\n\n${t("chand.disclaimer")}`;
}

