type Dashboard={referral_code:string;referral_url:string;message:string;counts:Record<string,number>;eligible_count:number;target:number;reward_amount:number;reward_status:string;available_balance:number;referrals:any[];ledger:any[];payout_integration:string};
export default function ReferralDashboardScreen(){
 const router=useRouter();const insets=useSafeAreaInsets();const {colors}=useTheme();const styles=useStyles();const {user}=useAuth();const [data,setData]=useState<Dashboard|null>(null);const [error,setError]=useState("");const [notice,setNotice]=useState("");const [loading,setLoading]=useState(true);
 const load=useCallback(()=>api.get<Dashboard>("/referrals/me").then(result=>{setData(result);setError("");}).catch((e:any)=>setError(e?.message||"Could not load Referral & Earn.")).finally(()=>setLoading(false)),[]);
 const referralUserKey=`${user?.id || ""}:${user?.role || ""}`;
 const [previousReferralUserKey,setPreviousReferralUserKey]=useState<string|null>(null);
 if(previousReferralUserKey!==referralUserKey){setPreviousReferralUserKey(referralUserKey);setLoading(user?.role==="customer");setError(user?.role==="customer"?"":"Referral & Earn is available to customer accounts only.");}
 useEffect(()=>{if(user?.role!=="customer")return;void load();},[user?.id,user?.role,load]);
 const share=async()=>{if(!data)return;try{const result=await Share.share({message:data.message,url:data.referral_url,title:"Join me on COME-IN"});setNotice(result.action==="sharedAction"?"Share sheet opened.":"Sharing cancelled.");}catch(e:any){setNotice(e?.message||"Could not open sharing options.");}};
 const copy=async()=>{if(!data)return;try{if(Platform.OS==="web"&&typeof navigator!=="undefined"&&navigator.clipboard?.writeText){await navigator.clipboard.writeText(data.referral_url);setNotice("Referral link copied.");return;}const result=await Share.share({message:data.referral_url,title:"COME-IN referral link"});setNotice(result.action==="sharedAction"?"Share sheet opened. Choose Copy to copy your referral link.":"Sharing cancelled.");}catch{setNotice("Could not copy the link. Use Share Link instead.");}};
 const whatsapp=async()=>{if(!data)return;if(Platform.OS==="web"){await Linking.openURL(`https://wa.me/?text=${encodeURIComponent(data.message)}`);setNotice("Opened WhatsApp web link.");return;}const url=`whatsapp://send?text=${encodeURIComponent(data.message)}`;try{await Linking.openURL(url);setNotice("WhatsApp opened.");}catch{try{await Linking.openURL(`https://wa.me/?text=${encodeURIComponent(data.message)}`);setNotice("Opened WhatsApp web link. Availability depends on the device.");}catch{setNotice("WhatsApp is unavailable. Copy Link or Share Link instead.");}}};
 const statusLabel=(s:string)=>({not_yet_earned:"Not Yet Earned",pending_verification:"Pending Verification",approved:"Approved",available:"Available",processing:"Processing",paid:"Paid",rejected:"Rejected"}[s]||s.replaceAll("_"," "));
 return <ScrollView style={styles.root} contentContainerStyle={{padding:spacing.lg,paddingTop:insets.top+spacing.md,paddingBottom:spacing.xxl,gap:spacing.md}}>
  <Pressable onPress={()=>router.back()} style={styles.back}><Feather name="arrow-left" size={20} color={colors.onSurface}/><Text style={styles.heading}>Referral & Earn</Text></Pressable>
  {loading?<Text style={styles.body}>Loading referral details…</Text>:error?<Text style={styles.error}>{error}</Text>:data&&<>
   <View style={styles.hero}><Feather name="gift" size={28} color={colors.brandPrimary}/><Text style={styles.title}>Invite friends to COME-IN</Text><Text style={styles.body}>Share your unique link. A referral counts toward the target only after an eligible purchase is delivered and payment, refund/return, and fraud checks are verified.</Text><Text style={styles.label}>Your referral code</Text><Text selectable style={styles.code}>{data.referral_code}</Text><Text style={styles.label}>Your referral link</Text><Text selectable style={styles.link}>{data.referral_url}</Text>
