type R={id:string;name:string;status:string;available:boolean;city:string;phone?:string;address?:string;description?:string;cuisines?:string[];image_url?:string;delivery_available?:boolean;pickup_available?:boolean;payment_methods?:string[];delivery_fee?:number;tax_rate?:number;min_order?:number;estimated_minutes?:number};
