  <Text style={rs.heading}>Menu management</Text>{menu.length===0?<Text style={rs.muted}>No menu items yet.</Text>:menu.map(item=><View key={item.id} style={rs.card}><Text style={{color:t.text,fontWeight:'900'}}>{item.name} · ₹{item.price}</Text><Text style={rs.muted}>{item.category} · {item.available?'Available':'Unavailable'}</Text><View style={rs.row}><TextInput value={priceDrafts[item.id]??String(item.price)} onChangeText={v=>setPriceDrafts(prev=>({...prev,[item.id]:v}))} keyboardType="decimal-pad" style={[rs.input,{flex:1}]} placeholder="Price in ₹"/><Pressable style={[rs.button,{flex:1}]} onPress={()=>updatePrice(item)}><Text style={rs.buttonText}>Save price</Text></Pressable></View><View style={rs.row}><Pressable style={[rs.chip,{flex:1}]} onPress={()=>toggleItem(item)}><Text style={rs.chipText}>{item.available?'Mark unavailable':'Mark available'}</Text></Pressable><Pressable style={[rs.chip,{flex:1}]} onPress={()=>deleteItem(item)}><Text style={rs.chipText}>Delete item</Text></Pressable></View></View>)}
  <Text style={rs.heading}>Incoming orders</Text>{orders.length===0?<Text style={rs.muted}>No server-saved orders yet.</Text>:orders.map(o=><View key={o.id} style={rs.card}><Text style={{color:t.text,fontWeight:'900'}}>{o.ref} · ₹{o.total}</Text><Text style={rs.muted}>{o.status} · {(o.items||[]).map(i=>`${i.name} × ${i.quantity}`).join(', ')}</Text>{o.status==='placed'?<View style={rs.row}><Pressable style={[rs.button,{flex:1}]} onPress={()=>setStatus(o,'accepted')}><Text style={rs.buttonText}>Accept</Text></Pressable><Pressable style={[rs.chip,{flex:1}]} onPress={()=>setStatus(o,'rejected')}><Text style={rs.chipText}>Reject</Text></Pressable></View>:o.status==='accepted'?<Pressable style={rs.button} onPress={()=>setStatus(o,'preparing')}><Text style={rs.buttonText}>Start preparing</Text></Pressable>:o.status==='preparing'?<Pressable style={rs.button} onPress={()=>setStatus(o,'ready')}><Text style={rs.buttonText}>Mark ready</Text></Pressable>:o.status==='ready'?<Pressable style={rs.button} onPress={()=>setStatus(o,o.fulfillment==='pickup'?'picked_up':'out_for_delivery')}><Text style={rs.buttonText}>{o.fulfillment==='pickup'?'Mark picked up':'Send for delivery'}</Text></Pressable>:o.status==='out_for_delivery'?<Pressable style={rs.button} onPress={()=>setStatus(o,'delivered')}><Text style={rs.buttonText}>Mark delivered</Text></Pressable>:null}</View>)}</>:null}
  {message?<Text style={{color:t.primary,fontSize:12}}>{message}</Text>:null}<Pressable style={rs.chip} onPress={()=>router.replace('/restaurant' as never)}><Text style={rs.chipText}>Back to Restaurant Home</Text></Pressable>
 </RestaurantPage>;
}

import { useCallback, useState } from 'react';
import { ActivityIndicator, Pressable, Text, View } from 'react-native';
import { useFocusEffect, useRouter } from 'expo-router';

import { api } from '@/src/lib/api';
import { useAuth } from '@/src/store/auth';
import { RestaurantPage, rs } from '@/src/restaurant/RestaurantPage';
import { restaurantTheme as t } from '@/src/restaurant/theme';

type RestaurantOrder = {
  id: string;
  ref: string;
  restaurant_name: string;
  status: string;
  payment_method: string;
  payment_status: string;
  total: number;
  created_at: string;
  items: Array<{ name?: string; quantity?: number }>;
  fulfillment: 'delivery' | 'pickup';
  delivery_address?: string;
};

export default function RestaurantOrdersScreen() {
  const router = useRouter();
  const { user } = useAuth();
  const [orders, setOrders] = useState<RestaurantOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const loadOrders = useCallback(async (isActive: () => boolean = () => true) => {
    if (!user || user.role !== 'customer') {
      if (isActive()) {
        setOrders([]);
        setLoading(false);
      }
      return;
    }
    if (isActive()) {
      setLoading(true);
      setError('');
    }
    try {
      const rows = await api.get<RestaurantOrder[]>('/restaurant/orders/mine');
      if (isActive()) setOrders(Array.isArray(rows) ? rows : []);
    } catch (e: any) {
      if (isActive()) setError(e?.message || 'Restaurant order history could not be loaded. Please try again.');
    } finally {
      if (isActive()) setLoading(false);
    }
  }, [user?.id, user?.role]);

  useFocusEffect(useCallback(() => {
    let active = true;
    void loadOrders(() => active);
    return () => { active = false; };
  }, [loadOrders]));

  return (
    <RestaurantPage title="Your restaurant orders" subtitle="Your restaurant orders only · grocery orders are shown separately">
      {user === null ? (
        <View style={rs.card}>
          <ActivityIndicator color={t.primary} />
          <Text style={rs.muted}>Checking your account…</Text>
        </View>
      ) : !user ? (
        <View style={rs.card}>
          <Text style={rs.muted}>Sign in to view your restaurant order history.</Text>
          <Pressable style={rs.button} onPress={() => router.push({ pathname: '/auth', params: { next: '/restaurant/orders' } } as never)}>
            <Text style={rs.buttonText}>Sign in</Text>
          </Pressable>
        </View>
      ) : user.role !== 'customer' ? (
        <View style={rs.card}>
          <Text style={rs.muted}>Restaurant order history is available to customer accounts. Your restaurant incoming orders remain in the Restaurant Dashboard.</Text>
        </View>
      ) : loading ? (
        <View style={rs.card}>
          <ActivityIndicator color={t.primary} />
          <Text style={rs.muted}>Loading your restaurant orders…</Text>
        </View>
      ) : error ? (
        <View style={rs.card}>
          <Text style={rs.muted}>{error}</Text>
          <Pressable style={rs.button} onPress={() => { void loadOrders(); }}>
            <Text style={rs.buttonText}>Try again</Text>
          </Pressable>
        </View>
      ) : orders.length === 0 ? (
        <View style={rs.card}>
          <Text style={rs.heading}>No restaurant orders yet</Text>
          <Text style={rs.muted}>When you place a restaurant order, it will appear here. Grocery orders are kept in your separate order history.</Text>
          <Pressable style={rs.button} onPress={() => router.replace('/restaurant' as never)}>
            <Text style={rs.buttonText}>Explore restaurants</Text>
          </Pressable>
        </View>
      ) : (
        orders.map((order) => (
          <Pressable
            key={order.id}
            style={rs.card}
            onPress={() => router.push({ pathname: '/restaurant/orders/[id]', params: { id: order.id } } as never)}
            accessibilityRole="button"
            accessibilityLabel={`View restaurant order ${order.ref}`}
          >
            <View style={rs.row}>
              <Text style={[rs.heading, { flex: 1 }]}>{order.ref}</Text>
              <Text style={{ color: t.primary, fontSize: 11, fontWeight: '900' }}>{(order.status || 'unknown').replaceAll('_', ' ').toUpperCase()}</Text>
            </View>
            <Text style={rs.muted}>{order.restaurant_name} · ₹{order.total}</Text>
            <Text style={rs.muted}>{order.items?.length || 0} items · {order.fulfillment === 'pickup' ? 'Pickup' : 'Delivery'} · Payment: {order.payment_status}</Text>
            <Text style={rs.muted}>{order.created_at ? new Date(order.created_at).toLocaleString() : ''}</Text>
            <Text style={{ color: t.primary, fontSize: 12, fontWeight: '800' }}>View order details →</Text>
          </Pressable>
        ))
      )}
    </RestaurantPage>
  );
}

// Seller — Product management
import Feather from "@react-native-vector-icons/feather";
import { useRouter } from "expo-router";
