  name: string;
  brand: string;
  unit: string;
  price: number;
  mrp?: number;
  stock: number;
  image_url?: string;
  category_id: string;
  description: string;
  available: boolean;
  variants?: ProductVariant[];
  sell_by?: SellBy;
  measure?: MeasureDraft | null;
};

const EMPTY: Product = {
  id: "",
  name: "",
  brand: "",
  unit: "",
  price: 0,
  stock: 0,
  category_id: "",
  description: "",
  available: true,
  variants: [],
  sell_by: "pack",
  measure: null,
};

// Name/category starting points only. Sellers must enter their real unit, price,
// stock and optional product photo before a listing can be saved or sold.
