import Feather from "@react-native-vector-icons/feather";
import { Image } from "expo-image";
import { useLocalSearchParams, useRouter } from "expo-router";
import { useEffect, useMemo, useState } from "react";
import {
  FlatList,
  Platform,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { useT } from "@/src/i18n";
import { filterShops, OfflineShopType, Shop, ShopType, SHOPS } from "@/src/data/shops";
import { api, resolveImage } from "@/src/lib/api";
import { makeStyles, radius, spacing, useTheme } from "@/src/theme";

type TabKey = "all" | ShopType;

const TAB_ORDER: TabKey[] = ["all", "online", "offline"];

export default function ShopsScreen() {
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const params = useLocalSearchParams<{ type?: string }>();
  const styles = useStyles();
  const { colors } = useTheme();
  const { t } = useT();

  const [tab, setTab] = useState<TabKey>(
    params.type === "online" || params.type === "offline" ? params.type : "all",
  );
  const [query, setQuery] = useState("");
  const [openNowOnly, setOpenNowOnly] = useState(false);
  const [deliveryOnly, setDeliveryOnly] = useState(false);
  const [offlineShopType, setOfflineShopType] = useState<OfflineShopType | "all">("all");
  const [liveShops, setLiveShops] = useState<Shop[]>([]);

  // Pull approved shops from the backend and normalize them into the same
  // shape as the seed demo shops so the existing filter + render pipeline
  // works unchanged. Live shops always sort to the top.
  useEffect(() => {
    api.get<any[]>("/shops").then((rows) => {
      const normalized: Shop[] = rows.map((s) => ({
        id: s.id,
        name: s.name,
        tagline: s.tagline || "",
        type: (s.shop_type as ShopType) || "offline",
        offlineShopType: (s.offline_shop_type as OfflineShopType) || "grocery_kirana",
        categoryIds: s.category_ids || [],
        area: s.area || "",
        address: s.address || "",
        phone: s.phone || "",
        image: resolveImage(s.image_url) || "https://images.unsplash.com/photo-1604719312566-8912e9227c6a?w=600&q=80",
        openNow: Boolean(s.online),
        hours: s.hours || "",
        deliveryAvailable: Boolean(s.delivery_available),
        pickupAvailable: Boolean(s.pickup_available),
        productIds: [],
      }));
      setLiveShops(normalized);
    }).catch(() => setLiveShops([]));
  }, []);

  const shops = useMemo(() => {
    // Merge live + seed; dedupe by id in case of overlap.
    const merged = [...liveShops, ...SHOPS.filter((s) => !liveShops.some((l) => l.id === s.id))];
    const q = query.trim().toLowerCase();
    return merged.filter((s) => {
      if (tab === "online" && s.type === "offline") return false;
      if (tab === "offline" && s.type === "online") return false;
      if (openNowOnly && !s.openNow) return false;
      if (deliveryOnly && !s.deliveryAvailable) return false;
      if (tab === "offline" && offlineShopType !== "all" && (s.offlineShopType || "grocery_kirana") !== offlineShopType) return false;
      if (!q) return true;
      return `${s.name} ${s.tagline} ${s.area} ${s.address}`.toLowerCase().includes(q);
    });
  }, [tab, query, openNowOnly, deliveryOnly, offlineShopType, liveShops]);

  return (
    <View style={styles.root}>
      <View style={[styles.header, { paddingTop: insets.top + spacing.sm }]}>
        <Pressable testID="shops-back-btn" onPress={() => router.back()} style={styles.iconBtn}>
          <Feather name="arrow-left" size={20} color={colors.onSurface} />
        </Pressable>
        <View style={{ flex: 1 }}>
          <Text style={styles.title}>{t("shops.title")}</Text>
          <Text style={styles.sub}>{t("shops.sub")}</Text>
        </View>
      </View>

      <View style={styles.toolbar}>
        <View style={styles.inputWrap}>
          <Feather name="search" size={16} color={colors.muted} />
          <TextInput
            testID="shops-search"
            value={query}
            onChangeText={setQuery}
            placeholder={t("shops.searchPlaceholder")}
            placeholderTextColor={colors.muted}
            style={styles.input}
          />
          {query.length > 0 && (
            <Pressable testID="shops-clear" onPress={() => setQuery("")} hitSlop={10}>
              <Feather name="x-circle" size={16} color={colors.muted} />
            </Pressable>
          )}
        </View>

        <View style={styles.tabRow}>
          {TAB_ORDER.map((key) => (
            <Pressable
              key={key}
              testID={`shops-tab-${key}`}
              onPress={() => setTab(key)}
              style={[
                styles.tab,
                tab === key && {
                  backgroundColor: colors.brandPrimary,
                  borderColor: colors.brandPrimary,
                },
              ]}
            >
              <Text
                style={[
                  styles.tabText,
                  tab === key && { color: colors.onBrandPrimary },
                ]}
              >
                {t(`shops.tab.${key}`)}
              </Text>
            </Pressable>
          ))}
        </View>

        {tab === "offline" && <View style={{ flexDirection: "row", flexWrap: "wrap", gap: spacing.xs, paddingHorizontal: spacing.md, paddingTop: spacing.sm }}>
          {([
            ["all", "All offline shops"], ["grocery_kirana", "Grocery / Kirana"], ["chicken", "Chicken"], ["meat", "Meat"], ["fish", "Fish"],
            ["momos", "Momos"], ["burger", "Burger"], ["pizza", "Pizza"], ["chinese_food", "Chinese food"], ["chaat_golgappa", "Chaat & Golgappa"], ["other_food", "Other food"],
          ] as const).map(([value, label]) => <Pressable key={value} testID={`offline-type-${value}`} onPress={() => setOfflineShopType(value as OfflineShopType | "all")} style={[styles.chip, offlineShopType === value && { backgroundColor: colors.brandTertiary, borderColor: colors.brandPrimary }]}><Text style={[styles.chipText, offlineShopType === value && { color: colors.brandPrimary }]}>{label}</Text></Pressable>)}
        </View>}

        <View style={styles.filterRow}>
          <FilterChip
            testID="filter-open-now"
            icon="clock"
            label={t("shops.filter.openNow")}
            active={openNowOnly}
            onPress={() => setOpenNowOnly((v) => !v)}
          />
          <FilterChip
            testID="filter-delivery"
            icon="truck"
            label={t("shops.filter.delivery")}
            active={deliveryOnly}
            onPress={() => setDeliveryOnly((v) => !v)}
          />
        </View>
      </View>

      <Pressable
        testID="retail-price-compare"
        accessibilityRole="button"
        onPress={() => router.push("/retail-prices")}
        style={{ marginHorizontal: spacing.lg, marginTop: spacing.sm, paddingHorizontal: spacing.md, paddingVertical: spacing.sm, minHeight: 42, borderRadius: radius.md, backgroundColor: colors.brandPrimary, flexDirection: "row", alignItems: "center", justifyContent: "center", gap: spacing.sm }}
      >
        <Feather name="bar-chart-2" size={17} color={colors.onBrandPrimary} />
        <Text style={{ color: colors.onBrandPrimary, fontSize: 13, fontWeight: "800" }}>Compare Imported Retail Prices</Text>
      </Pressable>

      <FlatList
        testID="shops-list"
        data={shops}
        keyExtractor={(s) => s.id}
        contentContainerStyle={{
          padding: spacing.lg,
          paddingBottom: spacing.xxl,
          gap: spacing.md,
        }}
        ListEmptyComponent={
          <View style={styles.empty}>
            <Feather name="shopping-bag" size={28} color={colors.muted} />
            <Text style={styles.emptyText}>{t("shops.empty")}</Text>
          </View>
        }
        renderItem={({ item }) => (
          <ShopRow
            shop={item}
            onPress={() => router.push(`/shop/${item.id}`)}
          />
        )}
      />
    </View>
  );
}

function FilterChip({
  testID,
  icon,
  label,
  active,
  onPress,
}: {
  testID: string;
  icon: React.ComponentProps<typeof Feather>["name"];
  label: string;
  active: boolean;
  onPress: () => void;
}) {
  const styles = useStyles();
  const { colors } = useTheme();
  return (
    <Pressable
      testID={testID}
      onPress={onPress}
      style={[
        styles.chip,
        active && {
          backgroundColor: colors.brandTertiary,
          borderColor: colors.brandPrimary,
        },
      ]}
    >
      <Feather name={icon} size={12} color={active ? colors.brandPrimary : colors.muted} />
      <Text style={[styles.chipText, active && { color: colors.brandPrimary }]}>{label}</Text>
    </Pressable>
  );
}

function ShopRow({ shop, onPress }: { shop: Shop; onPress: () => void }) {
  const styles = useStyles();
  const { colors } = useTheme();
  const { t } = useT();
  const typeTag =
    shop.type === "online"
      ? t("shops.type.online")
      : shop.type === "offline"
      ? t("shops.type.offline")
      : t("shops.type.both");

  return (
    <Pressable testID={`shop-row-${shop.id}`} onPress={onPress} style={styles.card}>
      <Image source={shop.image} style={styles.img} contentFit="cover" />
      <View style={styles.info}>
        <View style={styles.rowBetween}>
          <Text style={styles.name} numberOfLines={1}>
            {shop.name}
          </Text>
          <View
            style={[
              styles.typePill,
              {
                backgroundColor:
                  shop.type === "offline" ? colors.brandSecondary : colors.brandTertiary,
              },
            ]}
          >
            <Text
              style={[
                styles.typePillText,
                {
                  color:
                    shop.type === "offline"
                      ? colors.onBrandSecondary
                      : colors.brandPrimary,
                },
              ]}
            >
              {typeTag}
            </Text>
          </View>
        </View>
        <Text style={styles.tagline} numberOfLines={1}>
          {shop.tagline}
        </Text>
        <View style={styles.metaRow}>
          <Feather name="map-pin" size={11} color={colors.muted} />
          <Text style={styles.metaText} numberOfLines={1}>
            {shop.area || shop.address || ""}
          </Text>
          {(shop.area || shop.address) ? <View style={styles.dot} /> : null}
          <Feather
            name="circle"
            size={9}
            color={shop.openNow ? colors.brandPrimary : colors.muted}
          />
          <Text
            style={[
              styles.metaText,
              { color: shop.openNow ? colors.brandPrimary : colors.muted },
            ]}
          >
            {shop.openNow ? t("shops.openNow") : t("shops.closed")}
          </Text>
        </View>
      </View>
    </Pressable>
  );
}

