// The three entry modes of the command guard.
// runArgs: shim mode -> exit 0 allow / 1 block (reason + alternate on stderr).
// runPreinstall: yarn lifecycle hook -> checks package.json deps against the list.
// runListCommands: print guarded binary names (drives sync-shims.sh).

const fs = require("fs");
const path = require("path");
const { loadRules, maybeLogSource } = require("./rules");
const { firstMatch, listBinaries } = require("./matcher");

// "$1" in reason/alternate is replaced with the blocked command's binary (first word).
function printBlock(subject, entry) {
  const bin = subject.split(" ")[0];
  console.error("");
  console.error(`Blocked: ${subject}`);
  if (entry.reason) console.error(`  Reason:      ${entry.reason.replace(/\$1/g, bin)}`);
  if (entry.alternate) console.error(`  Use instead: ${entry.alternate.replace(/\$1/g, bin)}`);
  console.error("");
}

function runArgs(cmd, args) {
  const { list, source } = loadRules();
  maybeLogSource(list, source);

  const subject = [cmd, ...args].join(" ").trim();
  const hit = firstMatch(list, subject);
  if (!hit || hit.entry.allowed) process.exit(0);
  printBlock(subject, hit.entry);
  process.exit(1);
}

// A dep in package.json is equivalent to having installed it via the one legit path
// (`yarn expo install`, since `yarn add` is blanket-blocked). Each dep is checked as
// that command, so editing package.json directly can't bypass the rules.
const INSTALL_FORM = "yarn expo install";

function runPreinstall() {
  const { list, source } = loadRules();
  maybeLogSource(list, source);

  let pkg;
  try {
    // Read the package being installed via cwd (yarn runs preinstall from the package root), NOT __dirname: cmd-guard.js may be a symlink (mono/mobile -> expo), and __dirname would resolve to the expo source and validate the wrong package.json.
    pkg = JSON.parse(fs.readFileSync(path.join(process.cwd(), "package.json"), "utf8"));
  } catch (e) {
    process.exit(0);
  }

  const deps = Object.keys({ ...pkg.dependencies, ...pkg.devDependencies });
  const hits = [];
  for (const dep of deps) {
    const hit = firstMatch(list, `${INSTALL_FORM} ${dep}`);
    if (hit && !hit.entry.allowed) hits.push({ dep, entry: hit.entry });
  }
  if (hits.length === 0) process.exit(0);

  console.error("");
  console.error("Disallowed packages found in package.json:");
  for (const h of hits) {
    console.error(`  ${h.dep}${h.entry.reason ? " - " + h.entry.reason : ""}${h.entry.alternate ? " (use: " + h.entry.alternate + ")" : ""}`);
  }
  console.error("");
  console.error("  Recovery: run `git checkout package.json` to undo the add.");
  console.error("");
  process.exit(1);
}

function runListCommands() {
  const { list } = loadRules();
  for (const name of listBinaries(list)) console.log(name);
  process.exit(0);
}

module.exports = { runArgs, runPreinstall, runListCommands };

const fs = require("fs");
const crypto = require("crypto");

const RULES_PATH = process.env.CMD_GUARD_RULES || "/opt/install-guard/rules.json";

const DEFAULT_LIST = {
  "yarn add ** expo-av* **": { allowed: false, reason: "expo-av is deprecated", alternate: "expo-audio / expo-video" },
  "yarn expo install ** expo-av* **": { allowed: false, reason: "expo-av is deprecated", alternate: "expo-audio / expo-video" },
  "yarn add ** expo-barcode-scanner* **": { allowed: false, reason: "deprecated", alternate: "expo-camera" },
  "yarn expo install ** expo-barcode-scanner* **": { allowed: false, reason: "deprecated", alternate: "expo-camera" },
  "yarn add ** expo-background-fetch* **": { allowed: false, reason: "deprecated", alternate: "expo-background-task" },
  "yarn expo install ** expo-background-fetch* **": { allowed: false, reason: "deprecated", alternate: "expo-background-task" },
  "yarn add ** expo-file-system/legacy* **": { allowed: false, reason: "deprecated", alternate: "expo-file-system" },
  "yarn expo install ** expo-file-system/legacy* **": { allowed: false, reason: "deprecated", alternate: "expo-file-system" },
};

function isFlatList(parsed) {
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return false;
  const values = Object.values(parsed);
  return values.length > 0 && values.every((v) => v && typeof v === "object" && typeof v.allowed === "boolean");
}

function loadRules() {
  // Fail-closed: a MISSING file means no injection (baked default); a present-but-unreadable/malformed/invalid file rejects rather than silently dropping injected-only prohibitions.
  let raw;
  try {
    raw = fs.readFileSync(RULES_PATH, "utf8");
  } catch (e) {
    if (e && e.code === "ENOENT") return { list: DEFAULT_LIST, source: "baked" };
    throw new Error(`cmd-guard: injected rules at ${RULES_PATH} are unreadable (${(e && e.code) || e}); refusing to fall back to baked rules`);
  }
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(`cmd-guard: injected rules at ${RULES_PATH} are not valid JSON; refusing to fall back to baked rules`);
  }
  if (!isFlatList(parsed)) {
    throw new Error(`cmd-guard: injected rules at ${RULES_PATH} are not a valid rule list; refusing to fall back to baked rules`);
  }
  return { list: parsed, source: "injected" };
}

// CMD_GUARD_DEBUG=1 prints which ruleset is active (injected vs baked) + a content hash.
function maybeLogSource(list, source) {
  if (!process.env.CMD_GUARD_DEBUG) return;
  const sha = crypto.createHash("sha256").update(JSON.stringify(list)).digest("hex").slice(0, 8);
  console.error(`cmd-guard: rules source=${source} sha=${sha}`);
}

module.exports = { loadRules, maybeLogSource };

import { useEffect, useState } from "react";
import { Pressable, Text, TextInput, View } from "react-native";

import type { Product } from "@/src/data/catalog";
import { useT } from "@/src/i18n";
import { api } from "@/src/lib/api";
import { amountError, bigUnit, formatAmount, lineAmount, smallUnit } from "@/src/lib/measure";
import { makeStyles, radius, spacing, useTheme } from "@/src/theme";

type Props = { product: Product; cartQty: number; onSave: (qty: number) => string | null };
type ServerPrice = { qty: number; line_total: number; quantity_label: string };

export function MeasuredQuantityPicker({ product, cartQty, onSave }: Props) {
  const styles = useStyles();
  const { colors } = useTheme();
  const { t } = useT();
  const m = product.measure!;
  const presets = m.presets.length ? m.presets : [m.min_qty];
  const [amount, setAmount] = useState(cartQty || presets[0]);
  const [custom, setCustom] = useState("");
  const [server, setServer] = useState<ServerPrice | null>(null);
  const [message, setMessage] = useState("");
  const error = amountError(product, amount, t);

  const [previousCartQty, setPreviousCartQty] = useState(cartQty);
  if (previousCartQty !== cartQty) {
    setPreviousCartQty(cartQty);
    if (cartQty) setAmount(cartQty);
  }
  const priceKey = `${product.id}:${amount}:${error || ""}`;
  const [previousPriceKey, setPreviousPriceKey] = useState(priceKey);
  if (previousPriceKey !== priceKey) {
    setPreviousPriceKey(priceKey);
    setServer(null);
  }
  useEffect(() => {
    let active = true;
    if (error) return () => { active = false; };
    const timer = setTimeout(() => {
      api.post<ServerPrice>("/grocery/measured-price", { product_id: product.id, qty: amount })
        .then((r) => { if (active) setServer(r); })
        .catch((e: any) => { if (active) setMessage(e?.message || t("m.priceError")); });
    }, 300);
    return () => { active = false; clearTimeout(timer); };
  }, [amount, product.id, error]);

  const applyCustom = (text: string) => {
    setCustom(text);
    setMessage("");
    const n = Number(text);
    if (!text.trim()) setAmount(cartQty || presets[0]);
    else setAmount(/^\d+$/.test(text.trim()) && Number.isFinite(n) ? n : 0);
  };
  const save = () => { const err = onSave(amount); setMessage(err || t("m.saved", { amount: formatAmount(product, amount) })); };

  return (
    <View style={styles.wrap} testID="measured-picker">
      <Text style={styles.title}>{t("m.chooseAmount", { price: product.price, unit: bigUnit(product) })}</Text>
      <View style={styles.chips}>
        {presets.map((p) => {
          const selected = p === amount && !custom;
          const disabled = Boolean(amountError(product, p));
          return (
            <Pressable key={p} testID={`measured-preset-${p}`} disabled={disabled} onPress={() => { setCustom(""); setMessage(""); setAmount(p); }} style={[styles.chip, selected && styles.chipOn, disabled && { opacity: 0.4 }]}>
              <Text style={[styles.chipText, selected && { color: colors.brandPrimary }]}>{formatAmount(product, p)}</Text>
              <Text style={styles.chipSub}>₹{lineAmount(product, p).toFixed(2)}</Text>
            </Pressable>
          );
        })}
      </View>
      <Text style={styles.label}>{t("m.typeExact", { small: smallUnit(product), min: formatAmount(product, m.min_qty), max: formatAmount(product, m.max_qty), step: m.step })}</Text>
      <TextInput testID="measured-custom-input" value={custom} onChangeText={applyCustom} keyboardType="number-pad" placeholder={`e.g. ${m.min_qty + m.step}`} placeholderTextColor={colors.muted} style={styles.input} />
      {error ? <Text style={styles.error} accessibilityRole="alert" testID="measured-error">{error}</Text> : (
        <Text style={styles.price} testID="measured-server-price">
          {server && server.qty === amount ? t("m.exactPrice", { total: server.line_total.toFixed(2), amount: server.quantity_label }) : t("m.confirming")}
        </Text>
      )}
      <Pressable testID="measured-save-btn" disabled={Boolean(error)} onPress={save} style={[styles.button, error && { opacity: 0.45 }]}>
        <Text style={styles.buttonText}>{t(cartQty ? "m.updateCart" : "m.addToCart", { amount: formatAmount(product, amount) })}</Text>
      </Pressable>
      {message ? <Text style={styles.note} testID="measured-message">{message}</Text> : null}
    </View>
  );
}

