export function QuantityStepper({ qty, onAdd, onInc, onDec, size = "sm", testID, label }: Props) {
  const styles = useStyles();
  const { colors } = useTheme();

  const haptic = () => {
    Haptics.selectionAsync().catch(() => {});
  };

  if (qty === 0) {
    return (
      <Pressable
        testID={testID ?? "add-to-cart-btn"}
        onPress={() => {
          haptic();
          onAdd();
        }}
        style={({ pressed }) => [
          size === "sm" ? styles.addBtnSm : styles.addBtnMd,
          pressed && { opacity: 0.85 },
        ]}
      >
        <Text style={size === "sm" ? styles.addTextSm : styles.addTextMd}>ADD</Text>
      </Pressable>
    );
  }

  return (
    <View
      testID={testID ?? "qty-stepper"}
      style={size === "sm" ? styles.stepperSm : styles.stepperMd}
    >
      <Pressable
        testID="qty-dec-btn"
        onPress={() => {
          haptic();
          onDec();
        }}
        style={styles.stepBtn}
        hitSlop={6}
      >
        <Feather name="minus" size={size === "sm" ? 14 : 18} color={colors.onBrandPrimary} />
      </Pressable>
      <Text style={size === "sm" ? styles.qtyTextSm : styles.qtyTextMd}>{label ?? qty}</Text>
      <Pressable
        testID="qty-inc-btn"
        onPress={() => {
          haptic();
          onInc();
        }}
        style={styles.stepBtn}
        hitSlop={6}
      >
        <Feather name="plus" size={size === "sm" ? 14 : 18} color={colors.onBrandPrimary} />
      </Pressable>
    </View>
  );
}

