function referenceId(categoryId: string, name: string): string {
  const slug = name.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 64);
  return `ref-${categoryId}-${slug}`;
}

const DEMO_NAME_KEYS = new Set(DEMO_PRODUCTS_WITH_SOURCE.map((p) => `${p.categoryId}:${p.name.trim().toLocaleLowerCase()}`));
const REFERENCE_PRODUCTS: Product[] = Object.entries(REFERENCE_CATALOG).flatMap(([referenceCategory, names]) => {
  const categoryId = REFERENCE_CATEGORY_IDS[referenceCategory];
  if (!categoryId) return [];
  const seen = new Set<string>();
  return names.filter((name) => {
    const key = name.trim().toLocaleLowerCase();
    if (seen.has(key) || DEMO_NAME_KEYS.has(`${categoryId}:${key}`)) return false;
    seen.add(key);
    return true;
  }).map((name) => ({
    id: referenceId(categoryId, name), name, brand: "", unit: "", price: 0,
    image: referenceProductImage(categoryId, name),
    categoryId, description: "Catalog reference only. A shop must publish its own verified listing, pack size, price and stock before this item can be ordered.", source: "catalog" as const,
  }));
});

